create table public.payments (id text default (gen_random_uuid())::text not null,patient_id text,patient_name text,amount numeric(12,2) not null,payment_date date default CURRENT_DATE not null,method text default 'pix'::text not null,status text default 'paid'::text not null,receipt_url text,type text default 'particular'::text not null,insurance_name text,created_at timestamp with time zone default now() not null,clinic_id text,due_date date,receipt_file_name text,receipt_content_type text,specialty text,notes text,created_by text,updated_at timestamp with time zone default now(),base_amount numeric,additional_amount numeric,additional_scope text,is_recurring boolean default false,recurrence_group_id text,recurrence_index integer,recurrence_total integer,recurrence_frequency text,organization_id uuid,appointment_id uuid,professional_id uuid,service_type text,appointment_scheduled_at timestamp with time zone,payer_name text,competence_month date,original_amount numeric(14,2),discount_amount numeric(14,2) default 0 not null,paid_amount numeric(14,2) default 0 not null,refunded_amount numeric(14,2) default 0 not null,balance_amount numeric(14,2) default 0 not null,financial_status text,is_courtesy boolean default false not null,source text,idempotency_key text,last_payment_at timestamp with time zone,canceled_at timestamp with time zone,canceled_by text,adjustment_reason text,payer_id uuid,service_catalog_id uuid,private_price_rule_id uuid,patient_pricing_agreement_id uuid,financial_snapshot_id uuid,private_price_source text,private_price_source_label text,private_financial_classification text,cancellation_free_until timestamp with time zone,pricing_override_reason text,series_request_hash text,billing_frequency text,pricing_unit text,aggregation_method text,monthly_billing_group_key text,patient_financial_plan_logical_id uuid,monthly_session_count integer default 0 not null,monthly_adjustment_required boolean default false not null);
alter table public.payments add constraint payments_amount_check CHECK ((amount >= (0)::numeric));
alter table public.payments add constraint payments_pkey PRIMARY KEY (id);
alter table public.payments add constraint payments_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'partial'::text, 'paid'::text, 'canceled'::text, 'cancelled'::text, 'refunded'::text, 'delinquent'::text, 'overdue'::text, 'courtesy'::text, 'forecast'::text])));
create table public.private_session_price_rules (id uuid default gen_random_uuid() not null,organization_id uuid not null,scope_type text not null,specialty_key text,specialty_name text,service_catalog_id uuid,service_name_snapshot text,base_amount numeric(14,2) not null,default_duration_minutes integer default 50 not null,cancellation_free_value integer default 0 not null,cancellation_free_unit text default 'HOURS'::text not null,late_cancellation_type text default 'NO_CHARGE'::text not null,late_cancellation_value numeric(14,2) default 0 not null,no_show_type text default 'NO_CHARGE'::text not null,no_show_value numeric(14,2) default 0 not null,due_rule text default 'SESSION_DATE'::text not null,due_offset_days integer default 0 not null,due_day integer,expected_payment_method text,allow_partial_payment boolean default true not null,allowed_payment_methods text[] default ARRAY['pix'::text, 'cash'::text, 'card'::text, 'transfer'::text, 'boleto'::text, 'other'::text] not null,allow_manual_override boolean default false not null,discount_approval_required boolean default true not null,home_surcharge numeric(14,2) default 0 not null,school_surcharge numeric(14,2) default 0 not null,active boolean default true not null,valid_from date default CURRENT_DATE not null,valid_until date,version integer default 1 not null,replaces_rule_id uuid,idempotency_key text,request_hash text,created_by uuid,updated_by uuid,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null);
alter table public.private_session_price_rules add constraint private_session_price_rules_allowed_methods_check CHECK (((cardinality(allowed_payment_methods) > 0) AND ((expected_payment_method IS NULL) OR (expected_payment_method = ANY (allowed_payment_methods)))));
alter table public.private_session_price_rules add constraint private_session_price_rules_base_amount_check CHECK ((base_amount > (0)::numeric));
alter table public.private_session_price_rules add constraint private_session_price_rules_cancellation_free_unit_check CHECK ((cancellation_free_unit = ANY (ARRAY['HOURS'::text, 'DAYS'::text])));
alter table public.private_session_price_rules add constraint private_session_price_rules_cancellation_free_value_check CHECK (((cancellation_free_value >= 0) AND (cancellation_free_value <= 720)));
alter table public.private_session_price_rules add constraint private_session_price_rules_default_duration_minutes_check CHECK (((default_duration_minutes >= 15) AND (default_duration_minutes <= 720)));
alter table public.private_session_price_rules add constraint private_session_price_rules_due_day_check CHECK (((due_day >= 1) AND (due_day <= 31)));
alter table public.private_session_price_rules add constraint private_session_price_rules_due_offset_days_check CHECK (((due_offset_days >= 0) AND (due_offset_days <= 365)));
alter table public.private_session_price_rules add constraint private_session_price_rules_due_rule_check CHECK ((due_rule = ANY (ARRAY['APPOINTMENT_DATE'::text, 'SESSION_DATE'::text, 'DAYS_BEFORE'::text, 'DAYS_AFTER'::text, 'FIXED_DAY'::text])));
alter table public.private_session_price_rules add constraint private_session_price_rules_fixed_day_check CHECK (((due_rule <> 'FIXED_DAY'::text) OR (due_day IS NOT NULL)));
alter table public.private_session_price_rules add constraint private_session_price_rules_home_surcharge_check CHECK ((home_surcharge >= (0)::numeric));
alter table public.private_session_price_rules add constraint private_session_price_rules_late_cancellation_type_check CHECK ((late_cancellation_type = ANY (ARRAY['NO_CHARGE'::text, 'FULL'::text, 'PERCENTAGE'::text, 'FIXED'::text, 'MANUAL'::text])));
alter table public.private_session_price_rules add constraint private_session_price_rules_late_cancellation_value_check CHECK ((late_cancellation_value >= (0)::numeric));
alter table public.private_session_price_rules add constraint private_session_price_rules_no_show_type_check CHECK ((no_show_type = ANY (ARRAY['NO_CHARGE'::text, 'FULL'::text, 'PERCENTAGE'::text, 'FIXED'::text, 'MANUAL'::text])));
alter table public.private_session_price_rules add constraint private_session_price_rules_no_show_value_check CHECK ((no_show_value >= (0)::numeric));
alter table public.private_session_price_rules add constraint private_session_price_rules_percentage_check CHECK ((((late_cancellation_type <> 'PERCENTAGE'::text) OR (late_cancellation_value <= (100)::numeric)) AND ((no_show_type <> 'PERCENTAGE'::text) OR (no_show_value <= (100)::numeric))));
alter table public.private_session_price_rules add constraint private_session_price_rules_pkey PRIMARY KEY (id);
alter table public.private_session_price_rules add constraint private_session_price_rules_school_surcharge_check CHECK ((school_surcharge >= (0)::numeric));
alter table public.private_session_price_rules add constraint private_session_price_rules_scope_check CHECK ((((scope_type = 'CLINIC_DEFAULT'::text) AND (specialty_key IS NULL) AND (service_catalog_id IS NULL)) OR ((scope_type = 'SPECIALTY'::text) AND (NULLIF(TRIM(BOTH FROM specialty_key), ''::text) IS NOT NULL) AND (service_catalog_id IS NULL)) OR ((scope_type = 'SERVICE'::text) AND (service_catalog_id IS NOT NULL))));
alter table public.private_session_price_rules add constraint private_session_price_rules_scope_type_check CHECK ((scope_type = ANY (ARRAY['CLINIC_DEFAULT'::text, 'SPECIALTY'::text, 'SERVICE'::text])));
alter table public.private_session_price_rules add constraint private_session_price_rules_validity_check CHECK (((valid_until IS NULL) OR (valid_until >= valid_from)));
alter table public.private_session_price_rules add constraint private_session_price_rules_version_check CHECK ((version > 0));
create table public.tuss_service_catalog (id uuid default gen_random_uuid() not null,organization_id uuid not null,internal_code text,name text not null,description text,specialty text,service_type text,default_duration_minutes integer,billing_unit text default 'session'::text not null,default_quantity numeric(12,4) default 1 not null,default_amount_cents integer,active boolean default true not null,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null,created_by uuid,updated_by uuid);
alter table public.tuss_service_catalog add constraint tuss_service_catalog_billing_unit_check CHECK ((billing_unit = ANY (ARRAY['session'::text, 'hour'::text, 'minute'::text, 'unit'::text, 'package'::text])));
alter table public.tuss_service_catalog add constraint tuss_service_catalog_default_amount_check CHECK (((default_amount_cents IS NULL) OR (default_amount_cents >= 0)));
alter table public.tuss_service_catalog add constraint tuss_service_catalog_default_duration_check CHECK (((default_duration_minutes IS NULL) OR (default_duration_minutes > 0)));
alter table public.tuss_service_catalog add constraint tuss_service_catalog_default_quantity_check CHECK ((default_quantity > (0)::numeric));
alter table public.tuss_service_catalog add constraint tuss_service_catalog_pkey PRIMARY KEY (id);
create table public.users (id uuid not null,email text not null,name text,role text default 'therapist'::text,clinic_id uuid,subscription_status text default 'pending'::text,plan_name text,plan_price numeric,profile_picture text,specialty text,crp text,created_at timestamp with time zone default now(),updated_at timestamp with time zone default now(),age integer,type text,first_login_completed boolean default false,stripe_customer_id text,stripe_customer_email text,stripe_subscription_id text,stripe_subscription_item_id text,stripe_payment_failed_at timestamp with time zone,stripe_access_block_at timestamp with time zone,stripe_last_failed_invoice_id text,billing_model text default 'active_patients'::text,stripe_price_id text,is_demo_user boolean default false not null,demo_role text,demo_expires_at timestamp with time zone,demo_access_mode text,current_active_patient_limit integer,current_active_patient_count integer default 0,pending_billing_quantity integer,pending_effective_date timestamp with time zone,pending_billing_status text,pending_billing_requested_at timestamp with time zone,pending_billing_requested_by uuid,two_factor_enabled boolean default false not null,two_factor_secret text,billing_source text,complimentary_plan_granted_at timestamp with time zone,complimentary_plan_granted_by uuid,complimentary_plan_note text);
alter table public.users add constraint users_billing_source_check CHECK (((billing_source IS NULL) OR (billing_source = ANY (ARRAY['stripe'::text, 'complimentary'::text]))));
